import{_ as t}from"./chunks/home.pc.en.BIVUBvtu.js";import{_ as o}from"./chunks/maintenance-pwr.pc.en.CVW_nHka.js";import{_ as a,o as r,c as n,a5 as s}from"./chunks/framework.D47SInms.js";const i="/RBQ/nightly/images/app/dashboard-vision.pc.en.png",v=JSON.parse('{"title":"No camera view","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/no-camera-view.md","filePath":"manual/troubleshooting/no-camera-view.md","lastUpdated":1791600043000}'),h={name:"manual/troubleshooting/no-camera-view.md"};function c(d,e,l,p,u,m){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="no-camera-view" tabindex="-1">No camera view <a class="header-anchor" href="#no-camera-view" aria-label="Permalink to &quot;No camera view&quot;">​</a></h1><p>The robot is connected, but no camera video appears in the app. Work through the steps below.</p><h2 id="source" tabindex="-1">1. Check which source you are on <a class="header-anchor" href="#source" aria-label="Permalink to &quot;1. Check which source you are on {#source}&quot;">​</a></h2><p>If the viewport is on <code>3D</code>, it shows the robot&#39;s 3D pose rather than video — that is not a fault.</p><p><img src="'+t+'" alt="The viewport and its source name"></p><p>Tap the <strong>source name above the center of the viewport</strong> to open the list and pick a camera source such as <code>Front</code>. The list contains <strong>only the cameras the robot actually reports</strong>, so if the source you want is missing, that camera is not reaching the robot — go to step 2.</p><p>Which devices each source needs is listed in <a href="/RBQ/nightly/manual/gui/camera-vision.html">Camera &amp; Vision</a>.</p><h2 id="vision-status" tabindex="-1">2. Check the vision status <a class="header-anchor" href="#vision-status" aria-label="Permalink to &quot;2. Check the vision status {#vision-status}&quot;">​</a></h2><p>Open the <strong>Dashboard</strong> and go to the <strong>Vision</strong> tab — it is only visible in <a href="/RBQ/nightly/manual/gui/developer-mode.html">developer mode</a>.</p><p><img src="'+i+'" alt="Dashboard vision tab"></p><ul><li>Look at <strong>daemon connection</strong> and <strong>sensor count</strong> first. With no daemon attached the whole video path is down.</li><li>In the <strong>Vision sensors</strong> table, check each sensor&#39;s <code>STATUS</code> and <code>RGB / IR / 3D fps</code>. An fps of 0 means no frames are coming from that sensor.</li></ul><p>To start and stop the vision programs by hand, use <code>Vision Programs</code> under <strong>Maintenance → Vision</strong> (see <a href="/RBQ/nightly/manual/gui/maintenance.html">Maintenance</a>).</p><h2 id="power" tabindex="-1">3. Check camera power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;3. Check camera power {#power}&quot;">​</a></h2><p>A camera with no power appears in neither the list nor the video.</p><p><img src="'+o+'" alt="Maintenance power screen"></p><p>Under <strong>Maintenance → Power / System</strong>, check that these are on.</p><table tabindex="0"><thead><tr><th>Item</th><th>What it cuts</th></tr></thead><tbody><tr><td><code>Cameras (5V)</code></td><td>The body vision cameras — turning it off stops the video</td></tr><tr><td><code>Vision PC (12V)</code></td><td>The vision PC — cuts the cameras, audio and part of the telemetry on this screen</td></tr><tr><td><code>CCTV (12V)</code> · <code>Thermal (12V)</code></td><td>The color and thermal cameras of the PTZ unit</td></tr></tbody></table><h2 id="resolution" tabindex="-1">4. Try a lower resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;4. Try a lower resolution {#resolution}&quot;">​</a></h2><p>On a weak wireless link the video may not come up at all. Tap the <strong>resolution tile</strong> on the <strong>Observation</strong> card at the right and drop to <code>SQHD 540</code> or <code>Economy 360</code>.</p><h2 id="reconnect" tabindex="-1">5. Reconnect <a class="header-anchor" href="#reconnect" aria-label="Permalink to &quot;5. Reconnect {#reconnect}&quot;">​</a></h2><p>If everything above is fine and there is still no video, make the connection again.</p><p>Go back to the <strong>hub</strong> with the logo at the top left, tap the robot name (▾), and tap the robot&#39;s row in <strong>Select robot</strong> to connect again. Once the dot is green and the status line reads <code>Connected</code>, check whether the video returns.</p><h2 id="after-update" tabindex="-1">Right after a software update <a class="header-anchor" href="#after-update" aria-label="Permalink to &quot;Right after a software update {#after-update}&quot;">​</a></h2><p><strong>Cause:</strong> After a robot software update without a reboot, the vision programs sometimes fail to start properly.</p><p><strong>Fix:</strong> <strong>Reboot the robot</strong> — <code>System reboot</code> under <strong>Maintenance → Power / System</strong>.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Rebooting cuts motor power and the robot sags to the ground. <strong>Sit it down first</strong>, make sure it is resting on the floor, and do not move it until the reboot finishes.</p></div></div><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us how far through steps 1–5 you got, and which sensors showed 0 fps in the <strong>Vision sensors</strong> table.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Support</a></strong></p>',29)])])}const w=a(h,[["render",c]]);export{v as __pageData,w as default};
